const fs = require('fs');
const path = require('path');

const sessionsDir = path.join(__dirname, '.sessions');
const files = fs.readdirSync(sessionsDir).filter(f => f.endsWith('.json'));

let total = 0, completed = 0, totalTurns = 0;
const modelStats = {};

files.forEach(file => {
  const data = JSON.parse(fs.readFileSync(path.join(sessionsDir, file), 'utf8'));
  total++;
  if (data.status === 'completed') completed++;
  totalTurns += data.turn || 0;
  
  const model = data.model || 'unknown';
  modelStats[model] = (modelStats[model] || 0) + (data.status === 'completed' ? 1 : 0);
});

const top3 = Object.entries(modelStats)
  .sort((a, b) => b[1] - a[1])
  .slice(0, 3)
  .map(([model, wins]) => `${model}:${wins}`);

console.log(`total:${total}`);
console.log(`successRate:${(completed/total*100).toFixed(1)}%`);
console.log(`avgTurns:${(totalTurns/total).toFixed(1)}`);
console.log(`top3:${top3.join(',')}`);

