#!/usr/bin/env node
const fs = require('fs');
const path = require('path');

const sessionsDir = path.join(__dirname, '.sessions');
const files = fs.readdirSync(sessionsDir).filter(f => f.endsWith('.json'));

const sessions = files.map(f => JSON.parse(fs.readFileSync(path.join(sessionsDir, f), 'utf8')));
const byStatus = {};
sessions.forEach(s => {
  byStatus[s.status] = (byStatus[s.status] || 0) + 1;
});

const recent = sessions
  .sort((a,b) => new Date(b.timestamp||0) - new Date(a.timestamp||0))
  .slice(0, 5);

if (process.argv.includes('--overview')) {
  console.log('Status counts:');
  Object.entries(byStatus).forEach(([status, count]) => console.log(`  ${status}: ${count}`));
  console.log('\nLast 5 sessions:');
  recent.forEach(s => console.log(`  ${s.model||'unknown'} ${s.status} ${s.timestamp||'no-time'}`));
}
